 import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, uv, texture, mul } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new THREE.Group();
  root.userData.handlers = {};

  const palette = {
    ink: config.intent?.visualSpec?.colors?.ink ?? '#16161d',
    paper: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
    accent: config.intent?.visualSpec?.colors?.accent ?? '#ff2a38',
    surface: config.intent?.visualSpec?.colors?.surface ?? '#0b0b10',
  };

  const CARD_W = 2.8;
  const CARD_H = 0.74;
  const THUMB_W = 0.9;
  const THUMB_H = THUMB_W * (320 / 512);

  const inner = new THREE.Group();
  root.add(inner);

  const geometries = [];
  const materials = [];
  const textures = [];
  const timelines = [];

  const trackGeo = (g) => { geometries.push(g); return g; };
  const trackMat = (m) => { materials.push(m); return m; };
  const trackTex = (t) => { textures.push(t); return t; };
  const trackTl = (t) => { timelines.push(t); return t; };

  // card backdrop
  const cardGeo = trackGeo(new THREE.PlaneGeometry(CARD_W, CARD_H));
  const cardMat = trackMat(new MeshStandardNodeMaterial({
    colorNode: mix(color(palette.ink), color(palette.surface), uv().y),
    metalness: 0.3,
    roughness: 0.65,
    side: THREE.DoubleSide,
    transparent: true,
    opacity: 1,
  }));
  const card = new THREE.Mesh(cardGeo, cardMat);
  card.position.z = -0.04;
  inner.add(card);

  // subtle accent frame
  const halfW = CARD_W / 2;
  const halfH = CARD_H / 2;
  const frameZ = -0.035;
  const frameGeo = trackGeo(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-halfW, -halfH, frameZ),
    new THREE.Vector3(halfW, -halfH, frameZ),
    new THREE.Vector3(halfW, -halfH, frameZ),
    new THREE.Vector3(halfW, halfH, frameZ),
    new THREE.Vector3(halfW, halfH, frameZ),
    new THREE.Vector3(-halfW, halfH, frameZ),
    new THREE.Vector3(-halfW, halfH, frameZ),
    new THREE.Vector3(-halfW, -halfH, frameZ),
  ]));
  const frameMat = trackMat(new THREE.LineBasicMaterial({
    color: palette.accent,
    transparent: true,
    opacity: 0.05,
  }));
  const frame = new THREE.LineSegments(frameGeo, frameMat);
  inner.add(frame);

  // divider line
  const divGeo = trackGeo(new THREE.PlaneGeometry(CARD_W * 0.92, 0.008));
  const divMat = trackMat(new MeshBasicNodeMaterial({
    color: palette.paper,
    transparent: true,
    opacity: 0.12,
  }));
  const divider = new THREE.Mesh(divGeo, divMat);
  divider.position.set(0, -halfH + 0.06, 0.005);
  inner.add(divider);

  // parallax thumbnail
  const thumbGroup = new THREE.Group();
  thumbGroup.position.set(-halfW + THUMB_W * 0.5 + 0.2, 0.02, 0.02);
  inner.add(thumbGroup);

  const thumbGeo = trackGeo(new THREE.PlaneGeometry(THUMB_W, THUMB_H, 64, 64));
  const thumbMat = trackMat(new MeshStandardNodeMaterial({
    color: 0x050505,
    metalness: 0.2,
    roughness: 0.45,
    side: THREE.DoubleSide,
  }));
  const thumb = new THREE.Mesh(thumbGeo, thumbMat);
  thumbGroup.add(thumb);

  // async texture + depth load
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      trackTex(tex);
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearMipmapLinearFilter;
      tex.magFilter = THREE.LinearFilter;
      thumbMat.colorNode = texture(tex, uv());
      thumbMat.needsUpdate = true;
    }).catch(() => {});
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      trackTex(tex);
      tex.colorSpace = THREE.LinearSRGBColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      const dispScale = 0.08;
      thumbMat.displacementNode = mul(texture(tex, uv()).r, dispScale);
      thumbMat.needsUpdate = true;
    }).catch(() => {});
  }

  // text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  if (items.length) {
    const textGroup = new THREE.Group();
    textGroup.position.set(0.18, 0.05, 0.03);
    items.forEach((item, i) => {
      const copy = typeof item.text === 'string' ? item.text : '';
      if (!copy) return;
      const fontSize = item.typography?.fontSize ? item.typography.fontSize * 0.002 : i === 0 ? 0.18 : 0.11;
      const align = item.role === 'meta' ? 'left' : 'left';
      const label = ctx.fontAtlas.createText(copy, {
        fontSize,
        color: palette.paper,
        align,
      });
      label.position.set(0, (items.length - 1 - i) * 0.18 - 0.12, 0);
      textGroup.add(label);
    });
    inner.add(textGroup);
  }

  // idle parallax drift
  const idleTl = trackTl(gsap.to(thumbGroup.rotation, {
    y: 0.05,
    duration: 3.6,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut',
  }));

  // entrance
  cardMat.opacity = 0;
  divMat.opacity = 0;
  frameMat.opacity = 0;
  thumbMat.opacity = 0;
  inner.position.y = 0.3;

  const entranceTl = trackTl(gsap.timeline({ delay: 0.05 }));
  entranceTl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  entranceTl.to([cardMat, thumbMat], { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.08);
  entranceTl.to(divMat, { opacity: 0.12, duration: 0.5, ease: 'power2.out' }, 0.22);
  entranceTl.to(frameMat, { opacity: 0.05, duration: 0.5, ease: 'power2.out' }, 0.28);

  // interaction state
  const state = { hover: false, focus: false };

  const updateLift = () => {
    const targetY = state.hover || state.focus ? 0.15 : 0;
    gsap.to(inner.position, { y: targetY, duration: 0.4, ease: 'power2.out', overwrite: true });
  };

  const updateFrame = () => {
    const targetOp = state.hover || state.focus ? 0.75 : 0.05;
    gsap.to(frameMat, { opacity: targetOp, duration: 0.25, ease: 'power2.out' });
  };

  const press = () => {
    gsap.to(inner.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      yoyo: true,
      repeat: 1,
      ease: 'back.out(1.2)',
    });
  };

  root.userData.handlers.hover = (evt) => {
    const over = evt?.over !== false;
    state.hover = over;
    updateLift();
    updateFrame();
  };

  root.userData.handlers.hoverout = () => {
    state.hover = false;
    updateLift();
    updateFrame();
  };

  root.userData.handlers.focus = (evt) => {
    state.focus = evt?.focused !== false;
    updateLift();
    updateFrame();
  };

  root.userData.handlers.click = () => {
    press();
    ctx.emit('hub-features.select', { id: config.id });
  };

  root.userData.cleanup = () => {
    timelines.forEach((t) => { try { t.kill(); } catch (e) {} });
    textures.forEach((t) => { try { t.dispose(); } catch (e) {} });
    materials.forEach((m) => { try { m.dispose(); } catch (e) {} });
    geometries.forEach((g) => { try { g.dispose(); } catch (e) {} });
  };

  return root;
}
